                       constraints=cons,
                       options={'maxiter': 500, 'ftol': 1e-12},
                       callback=None)
        z = res.x
    except Exception:
        z = z0
    c, r = _unpack(z, n)
    return c, r


def _clean(c, r, n):
    r = np.maximum(r, 1e-6)
    for i in range(n):
        r[i] = min(r[i], c[i, 0], 1.0 - c[i, 0], c[i, 1], 1.0 - c[i, 1])
    r = np.maximum(r, 1e-6)
    for _ in range(50):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(c[i, 0] - c[j, 0], c[i, 1] - c[j, 1])
                s = r[i] + r[j]
                if d < s:
                    excess = s - d
                    r[i] -= excess / 2 + 1e-12
