    for j, cnt in enumerate(rows):
        y = (j + 0.5) / k
        for i in range(cnt):
            x = (i + 0.5) / cnt
            if j % 2 == 1:
                x = (x + 0.5 / cnt) % 1.0
            pts.append((x, y))
    pts = pts[:n]
    c = np.array(pts)
    r = np.full(n, r0)
    return c, r


def _active_set(c, r, n, tol=1e-6):
    """Return list of active constraints as ('pair', i, j) or ('wall', i, side)."""
    A = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(c[i, 0] - c[j, 0], c[i, 1] - c[j, 1])
            if d - (r[i] + r[j]) < tol:
                A.append(('pair', i, j))
        if c[i, 0] - r[i] < tol:
            A.append(('wall', i, 0))
        if 1.0 - c[i, 0] - r[i] < tol:
            A.append(('wall', i, 1))
        if c[i, 1] - r[i] < tol:
            A.append(('wall', i, 2))
        if 1.0 - c[i, 1] - r[i] < tol:
            A.append(('wall', i, 3))
    return A


def _residual(z, n, A):
    c, r = _unpack(z, n)
    out = np.empty(len(A))
    for k, a in enumerate(A):
        if a[0] == 'pair':
            i, j = a[1], a[2]
            dx = c[i, 0] - c[j, 0]
            dy = c[i, 1] - c[j, 1]
            out[k] = dx * dx + dy * dy - (r[i] + r[j]) ** 2
        else:
            i, side = a[1], a[2]
            if side == 0:
                out[k] = c[i, 0] - r[i]
            elif side == 1:
                out[k] = 1.0 - c[i, 0] - r[i]
            elif side == 2:
                out[k] = c[i, 1] - r[i]
            else:
                out[k] = 1.0 - c[i, 1] - r[i]
    return out


def _newton_active(c, r, n, tlimit):
    """Solve active-set equality system in least-squares sense."""
    z = _pack(c, r)
    for _ in range(2):
        A = _active_set(c, r, n, tol=1e-6)
        m = len(A)
        if m == 0 or m > 78:
