                                method='lm', max_nfev=200,
                                xtol=1e-15, ftol=1e-15, gtol=1e-15)
            z = res.x
        except Exception:
            break
        c, r = _unpack(z, n)
        if time.process_time() > tlimit:
            break
    return c, r


