import time
from scipy.optimize import minimize


def _unpack(z, n):
    c = z[:2 * n].reshape(n, 2)
    r = z[2 * n:]
    return c, r


def _objective(z, n):
    return -np.sum(z[2 * n:])


def _constraints(z, n, eq_pairs=None, eq_walls=None):
    eq_pairs = eq_pairs or set()
    eq_walls = eq_walls or set()
    cons = []

    def make_wall(idx, kind):
        if kind == 'xlo':
            f = lambda zz: _unpack(zz, n)[0][:, 0] - _unpack(zz, n)[1]
        elif kind == 'xhi':
            f = lambda zz: 1.0 - _unpack(zz, n)[0][:, 0] - _unpack(zz, n)[1]
        elif kind == 'ylo':
            f = lambda zz: _unpack(zz, n)[0][:, 1] - _unpack(zz, n)[1]
        else:
            f = lambda zz: 1.0 - _unpack(zz, n)[0][:, 1] - _unpack(zz, n)[1]
        return {'type': 'eq' if (idx, kind) in eq_walls else 'ineq', 'fun': f}

    for i in range(n):
        cons.append(make_wall(i, 'xlo'))
        cons.append(make_wall(i, 'xhi'))
        cons.append(make_wall(i, 'ylo'))
        cons.append(make_wall(i, 'yhi'))

    def pair_fun(zz):
        cc, rr = _unpack(zz, n)
        out = []
        for i in range(n):
            for j in range(i + 1, n):
                dx = cc[i, 0] - cc[j, 0]
                dy = cc[i, 1] - cc[j, 1]
                out.append(dx * dx + dy * dy - (rr[i] + rr[j]) ** 2)
        return np.array(out)

    # We need per-pair equality/inequality; SLSQP accepts arrays only as one type.
    # So split into two constraint dicts: equality pairs and inequality pairs.
    eq_list = sorted(eq_pairs)
    ineq_list = [(i, j) for i in range(n) for j in range(i + 1, n) if (i, j) not in eq_pairs]

    if eq_list:
        def eq_pair_fun(zz):
            cc, rr = _unpack(zz, n)
            out = []
            for (i, j) in eq_list:
                dx = cc[i, 0] - cc[j, 0]
                dy = cc[i, 1] - cc[j, 1]
                out.append(dx * dx + dy * dy - (rr[i] + rr[j]) ** 2)
            return np.array(out)
        cons.append({'type': 'eq', 'fun': eq_pair_fun})

    if ineq_list:
        def ineq_pair_fun(zz):
            cc, rr = _unpack(zz, n)
            out = []
            for (i, j) in ineq_list:
                dx = cc[i, 0] - cc[j, 0]
                dy = cc[i, 1] - cc[j, 1]
                out.append(dx * dx + dy * dy - (rr[i] + rr[j]) ** 2)
            return np.array(out)
        cons.append({'type': 'ineq', 'fun': ineq_pair_fun})

    cons.append({'type': 'ineq', 'fun': lambda zz: _unpack(zz, n)[1]})
    return cons


def _pack(c, r):
    return np.concatenate([c.ravel(), r])


def _run_slsqp(c0, r0, n, maxiter=400, eq_pairs=None, eq_walls=None, ftol=1e-12):
    z0 = _pack(c0, r0)
    cons = _constraints(z0, n, eq_pairs, eq_walls)
    try:
        res = minimize(_objective, z0, args=(n,), method='SLSQP',
                       constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol},
                       callback=None)
        z = res.x
        mult = res.multipliers if hasattr(res, 'multipliers') else None
    except Exception:
        z = z0
        mult = None
    c, r = _unpack(z, n)
    return c, r, mult


def _clean(c, r, n):
    r = np.maximum(r, 1e-6)
    for i in range(n):
        r[i] = min(r[i], c[i, 0], 1.0 - c[i, 0], c[i, 1], 1.0 - c[i, 1])
    r = np.maximum(r, 1e-6)
    for _ in range(50):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(c[i, 0] - c[j, 0], c[i, 1] - c[j, 1])
                s = r[i] + r[j]
                if d < s:
                    excess = s - d
                    r[i] -= excess / 2 + 1e-12
                    r[j] -= excess / 2 + 1e-12
                    changed = True
        r = np.maximum(r, 1e-6)
        if not changed:
            break
    return c, r


def _score(c, r):
    return np.sum(r)


def _init_rows(rows, n, r0=0.06):
    pts = []
    k = len(rows)
    for j, cnt in enumerate(rows):
        y = (j + 0.5) / k
        for i in range(cnt):
            x = (i + 0.5) / cnt
            if j % 2 == 1:
                x = (x + 0.5 / cnt) % 1.0
            pts.append((x, y))
    pts = pts[:n]
    c = np.array(pts)
    r = np.full(n, r0)
    return c, r


def _jitter(c, r, n, rng, scale=0.02):
    c2 = c + rng.normal(0.0, scale, size=c.shape)
    lo = r[:, None]
    hi = 1.0 - r[:, None]
    c2 = np.clip(c2, lo, hi)
    return c2


def _detect_active(c, r, n, tol=1e-5):
    eq_pairs = set()
    eq_walls = set()
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(c[i, 0] - c[j, 0], c[i, 1] - c[j, 1])
            if d - (r[i] + r[j]) < tol:
                eq_pairs.add((i, j))
        if r[i] - c[i, 0] < tol:
            eq_walls.add((i, 'xlo'))
        if 1.0 - c[i, 0] - r[i] < tol:
            eq_walls.add((i, 'xhi'))
        if r[i] - c[i, 1] < tol:
            eq_walls.add((i, 'ylo'))
        if 1.0 - c[i, 1] - r[i] < tol:
            eq_walls.add((i, 'yhi'))
    return eq_pairs, eq_walls


def _feasible(c, r, n, tol=1e-12):
    if np.any(r <= 0):
        return False
    for i in range(n):
        if c[i, 0] - r[i] < -tol or 1.0 - c[i, 0] - r[i] < -tol:
            return False
        if c[i, 1] - r[i] < -tol or 1.0 - c[i, 1] - r[i] < -tol:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(c[i, 0] - c[j, 0], c[i, 1] - c[j, 1])
            if d - (r[i] + r[j]) < -tol:
                return False
    return True


def _check_multipliers(mult, eq_pairs, eq_walls, n):
    """Return True if all equality multipliers are >= -1e-9, else the worst pair."""
    if mult is None:
        return True, None
    # SLSQP multipliers ordering: constraints in order they were added.
    # Order: walls (4n), then eq pairs, then ineq pairs, then r>=0.
    # We only care about equality constraints: walls that are eq, and eq pairs.
    idx = 0
    worst = None
    worst_val = 0.0
    # walls
    for i in range(n):
        for kind in ('xlo', 'xhi', 'ylo', 'yhi'):
            if (i, kind) in eq_walls:
                if idx < len(mult):
                    m = mult[idx]
                    if m < worst_val:
                        worst_val = m
                        worst = ('wall', i, kind)
            idx += 1
    # eq pairs
    for (i, j) in sorted(eq_pairs):
        if idx < len(mult):
            m = mult[idx]
            if m < worst_val:
                worst_val = m
                worst = ('pair', i, j)
        idx += 1
    return worst_val >= -1e-9, worst


def construct(budget_seconds, start):
    t_start = time.process_time()
    n = 26
    rng = np.random.default_rng(12345)

    row_patterns = [
        [5, 5, 5, 5, 6],
        [6, 5, 5, 5, 5],
        [5, 6, 5, 5, 5],
        [5, 5, 6, 5, 5],
        [5, 5, 5, 6, 5],
        [4, 6, 6, 5, 5],
        [6, 6, 5, 5, 4],
        [4, 5, 6, 6, 5],
        [5, 4, 6, 6, 5],
        [7, 5, 5, 5, 4],
        [4, 5, 5, 5, 7],
        [4, 5, 4, 5, 4, 4],
        [5, 4, 4, 4, 5, 4],
    ]

    best_c = None
    best_r = None
    best_s = -1.0

    if start is not None:
        s_arr = np.asarray(start, dtype=float)
        c0 = s_arr[:, :2].copy()
        r0 = s_arr[:, 2].copy()
        c, r = _clean(c0, r0, n)
        s = _score(c, r)
        if s > best_s:
            best_s = s
            best_c = c.copy()
            best_r = r.copy()

    candidates = []
    for rows in row_patterns:
        c0, r0 = _init_rows(rows, n)
        for _ in range(3):
            cj = _jitter(c0, r0, n, rng)
            candidates.append((cj, r0.copy()))

    for c0, r0 in candidates:
        if time.process_time() - t_start > budget_seconds - 2.5:
            break
        c, r, _ = _run_slsqp(c0, r0, n, maxiter=400)
        c, r = _clean(c, r, n)
        s = _score(c, r)
        if s > best_s:
            best_s = s
            best_c = c.copy()
            best_r = r.copy()

    if best_c is None:
        best_c, best_r = _init_rows([5, 5, 5, 5, 6], n)
        best_c, best_r = _clean(best_c, best_r, n)

    # Final full SLSQP from winner
    remaining = budget_seconds - (time.process_time() - t_start) - 0.5
    if remaining > 0.2:
        c, r, _ = _run_slsqp(best_c, best_r, n, maxiter=1000)
        c, r = _clean(c, r, n)
        if _score(c, r) > best_s:
            best_s = _score(c, r)
            best_c = c.copy()
            best_r = r.copy()

    # --- Equality-refinement step ---
    remaining = budget_seconds - (time.process_time() - t_start) - 0.3
    if remaining > 0.3:
        eq_pairs, eq_walls = _detect_active(best_c, best_r, n, tol=1e-5)
        c_eq, r_eq, mult = _run_slsqp(best_c, best_r, n, maxiter=2000,
                                      eq_pairs=eq_pairs, eq_walls=eq_walls,
                                      ftol=1e-14)
        ok, worst = _check_multipliers(mult, eq_pairs, eq_walls, n)
        if ok and _feasible(c_eq, r_eq, n, tol=1e-12) and _score(c_eq, r_eq) > best_s:
            best_c, best_r = c_eq, r_eq
            best_s = _score(best_c, best_r)
        elif not ok and worst is not None:
            # drop the worst pair and retry once
            if worst[0] == 'pair':
                eq_pairs.discard((worst[1], worst[2]))
            else:
                eq_walls.discard((worst[1], worst[2]))
            remaining = budget_seconds - (time.process_time() - t_start) - 0.3
            if remaining > 0.2:
                c_eq, r_eq, mult = _run_slsqp(best_c, best_r, n, maxiter=2000,
                                              eq_pairs=eq_pairs, eq_walls=eq_walls,
                                              ftol=1e-14)
                ok2, _ = _check_multipliers(mult, eq_pairs, eq_walls, n)
                if ok2 and _feasible(c_eq, r_eq, n, tol=1e-12) and _score(c_eq, r_eq) > best_s:
                    best_c, best_r = c_eq, r_eq
                    best_s = _score(best_c, best_r)

    best_r = best_r - 1e-9
    best_r = np.maximum(best_r, 1e-9)
    best_c, best_r = _clean(best_c, best_r, n)
    best_r = np.maximum(best_r - 1e-12, 1e-9)

    out = np.column_stack([best_c, best_r])
    return out

