        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(c[i, 0] - c[j, 0], c[i, 1] - c[j, 1])
                s = r[i] + r[j]
                if d < s:
                    excess = s - d
                    r[i] -= excess / 2 + 1e-12
                    r[j] -= excess / 2 + 1e-12
                    changed = True
        r = np.maximum(r, 1e-6)
        if not changed:
            break
    return c, r


def _score(c, r):
    return np.sum(r)


def _init_rows(rows, n, r0=0.06):
    pts = []
    k = len(rows)
    for j, cnt in enumerate(rows):
        y = (j + 0.5) / k
        for i in range(cnt):
            x = (i + 0.5) / cnt
            if j % 2 == 1:
                x = (x + 0.5 / cnt) % 1.0
            pts.append((x, y))
    pts = pts[:n]
    c = np.array(pts)
    r = np.full(n, r0)
    return c, r


def _jitter(c, r, n, rng, scale=0.02):
    c2 = c + rng.normal(0.0, scale, size=c.shape)
    lo = r[:, None]
    hi = 1.0 - r[:, None]
    c2 = np.clip(c2, lo, hi)
    return c2


def _affine_try(best_c, best_r, best_s, sx, sy, n, maxiter=200):
    c_t = 0.5 + (best_c - 0.5) * np.array([sx, sy])
    c_t = np.clip(c_t, 0.002, 0.998)
    r_t = _lp_radii(c_t, n)
    if r_t is None:
        return None
    r_t = np.maximum(r_t, 1e-6)
    c_t, r_t = _clean(c_t, r_t, n)
    c2, r2 = _run_slsqp(c_t, r_t, n, maxiter=maxiter)
    c2, r2 = _clean(c2, r2, n)
    s2 = _score(c2, r2)
    if s2 > best_s:
        return c2, r2, s2
    return None


def _inflate_project(c, r, n, sweeps=200, factor=1e-6):
    """Multiply radii by 1+factor, then project back to feasibility."""
    c = c.copy()
    r = r.copy() * (1.0 + factor)
    for _ in range(sweeps):
        # wall constraints: shrink r if needed
        for i in range(n):
            m = min(c[i, 0], 1.0 - c[i, 0], c[i, 1], 1.0 - c[i, 1])
            if r[i] > m:
                r[i] = m
        # pair constraints: move centers apart and shrink minimally
        for i in range(n):
            for j in range(i + 1, n):
                dx = c[i, 0] - c[j, 0]
                dy = c[i, 1] - c[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if d < s:
                    excess = s - d
                    # shrink radii minimally
                    r[i] -= excess / 2
                    r[j] -= excess / 2
                    if r[i] < 1e-9:
                        r[j] += r[i] - 1e-9
                        r[i] = 1e-9
                    if r[j] < 1e-9:
                        r[i] += r[j] - 1e-9
                        r[j] = 1e-9
        r = np.maximum(r, 1e-9)
    return c, r


def _active_set(c, r, n, tol=1e-8):
    """Identify active constraints: pairs touching and wall contacts."""
    pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(c[i, 0] - c[j, 0], c[i, 1] - c[j, 1])
            if abs(d - (r[i] + r[j])) < tol:
                pairs.append((i, j))
    walls = []
    for i in range(n):
        if abs(c[i, 0] - r[i]) < tol:
            walls.append((i, 0))
        if abs(1.0 - c[i, 0] - r[i]) < tol:
            walls.append((i, 1))
        if abs(c[i, 1] - r[i]) < tol:
            walls.append((i, 2))
        if abs(1.0 - c[i, 1] - r[i]) < tol:
            walls.append((i, 3))
    return pairs, walls


def _kkt_polish(c, r, n, pairs, walls):
    """Solve equality KKT system for active set."""
    if not pairs and not walls:
        return None
    # variables: centers (2n), radii (n), multipliers (len(pairs)+len(walls))
    nvar = 3 * n + len(pairs) + len(walls)

    def unpack(z):
        cc = z[:2 * n].reshape(n, 2)
        rr = z[2 * n:3 * n]
        lam = z[3 * n:]
        return cc, rr, lam

    def eqs(z):
        cc, rr, lam = unpack(z)
        out = []
        # stationarity: d/dx_i, d/dy_i of sum r + sum lam_k * g_k = 0
        # objective: -sum r (we minimize -sum r), gradient wrt r_i = -1
        # For pair constraint g = (xi-xj)^2+(yi-yj)^2-(ri+rj)^2, dg/dxi = 2(xi-xj)
        gx = np.zeros(n)
        gy = np.zeros(n)
        gr = -np.ones(n)
        k = 0
        for (i, j) in pairs:
            dx = cc[i, 0] - cc[j, 0]
            dy = cc[i, 1] - cc[j, 1]
            gx[i] += lam[k] * 2 * dx
            gx[j] -= lam[k] * 2 * dx
            gy[i] += lam[k] * 2 * dy
            gy[j] -= lam[k] * 2 * dy
            gr[i] += lam[k] * (-2 * (rr[i] + rr[j]))
            gr[j] += lam[k] * (-2 * (rr[i] + rr[j]))
            k += 1
        for (i, w) in walls:
            if w == 0:
                gx[i] += lam[k] * 1.0
                gr[i] += lam[k] * (-1.0)
            elif w == 1:
                gx[i] += lam[k] * (-1.0)
                gr[i] += lam[k] * (-1.0)
            elif w == 2:
                gy[i] += lam[k] * 1.0
                gr[i] += lam[k] * (-1.0)
            else:
                gy[i] += lam[k] * (-1.0)
                gr[i] += lam[k] * (-1.0)
            k += 1
        out.extend(gx.tolist())
        out.extend(gy.tolist())
        out.extend(gr.tolist())
        # constraint equalities
        for (i, j) in pairs:
            d2 = (cc[i, 0] - cc[j, 0]) ** 2 + (cc[i, 1] - cc[j, 1]) ** 2
            out.append(d2 - (rr[i] + rr[j]) ** 2)
        for (i, w) in walls:
            if w == 0:
                out.append(cc[i, 0] - rr[i])
            elif w == 1:
                out.append(1.0 - cc[i, 0] - rr[i])
            elif w == 2:
                out.append(cc[i, 1] - rr[i])
            else:
                out.append(1.0 - cc[i, 1] - rr[i])
        return np.array(out)

    z0 = np.concatenate([c.ravel(), r, np.zeros(len(pairs) + len(walls))])
    try:
        sol = root(eqs, z0, method='hybr', options={'maxfev': 2000})
        if not sol.success:
            return None
        cc, rr, lam = unpack(sol.x)
        return cc, rr
    except Exception:
        return None


def _is_valid(c, r, n, tol=0.0):
    for i in range(n):
        if r[i] <= 0:
            return False
        if c[i, 0] - r[i] < -tol or c[i, 0] + r[i] > 1.0 + tol:
            return False
        if c[i, 1] - r[i] < -tol or c[i, 1] + r[i] > 1.0 + tol:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(c[i, 0] - c[j, 0], c[i, 1] - c[j, 1])
            if d < r[i] + r[j] - tol:
                return False
    return True


def construct(budget_seconds, start):
    t_start = time.process_time()
    n = 26
    rng = np.random.default_rng(12345)

    row_patterns = [
        [5, 5, 5, 5, 6],
        [6, 5, 5, 5, 5],
        [5, 6, 5, 5, 5],
        [5, 5, 6, 5, 5],
        [5, 5, 5, 6, 5],
        [4, 6, 6, 5, 5],
        [6, 6, 5, 5, 4],
        [4, 5, 6, 6, 5],
        [5, 4, 6, 6, 5],
        [7, 5, 5, 5, 4],
        [4, 5, 5, 5, 7],
        [5, 5, 5, 5, 6],
        [4, 5, 4, 5, 4, 4],
        [5, 4, 4, 4, 5, 4],
    ]

    best_c = None
    best_r = None
    best_s = -1.0

    if start is not None:
        s_arr = np.asarray(start, dtype=float)
        c0 = s_arr[:, :2].copy()
        r0 = s_arr[:, 2].copy()
        c, r = _clean(c0, r0, n)
        s = _score(c, r)
        if s > best_s:
            best_s = s
            best_c = c.copy()
            best_r = r.copy()

    candidates = []
    for rows in row_patterns:
        c0, r0 = _init_rows(rows, n)
        for _ in range(3):
            cj = _jitter(c0, r0, n, rng)
            candidates.append((cj, r0.copy()))

    for c0, r0 in candidates:
        if time.process_time() - t_start > budget_seconds - 4.0:
            break
        c, r = _run_slsqp(c0, r0, n, maxiter=400)
        c, r = _clean(c, r, n)
        s = _score(c, r)
        if s > best_s:
            best_s = s
            best_c = c.copy()
            best_r = r.copy()

    if best_c is None:
        best_c, best_r = _init_rows([5, 5, 5, 5, 6], n)
        best_c, best_r = _clean(best_c, best_r, n)

    remaining = budget_seconds - (time.process_time() - t_start) - 3.0
    if remaining > 0.2:
        c, r = _run_slsqp(best_c, best_r, n, maxiter=1000)
        c, r = _clean(c, r, n)
        if _score(c, r) > best_s:
            best_s = _score(c, r)
            best_c = c.copy()
            best_r = r.copy()

    # Coarse 2D grid sx,sy in 0.80..1.20 step 0.02
    coarse_vals = np.arange(0.80, 1.201, 0.02)
    best_pair = None
    for sx in coarse_vals:
        if time.process_time() - t_start > budget_seconds - 2.5:
            break
        for sy in coarse_vals:
            if time.process_time() - t_start > budget_seconds - 2.5:
                break
            res = _affine_try(best_c, best_r, best_s, sx, sy, n, maxiter=200)
            if res is not None:
                best_c, best_r, best_s = res
                best_pair = (sx, sy)

    # Refine best (sx,sy) on 0.005 grid in +/-0.02
    if best_pair is not None:
        cx, cy = best_pair
        fine_vals_x = np.arange(cx - 0.02, cx + 0.0201, 0.005)
        fine_vals_y = np.arange(cy - 0.02, cy + 0.0201, 0.005)
        for sx in fine_vals_x:
            if time.process_time() - t_start > budget_seconds - 1.5:
                break
            for sy in fine_vals_y:
                if time.process_time() - t_start > budget_seconds - 1.5:
                    break
                res = _affine_try(best_c, best_r, best_s, sx, sy, n, maxiter=200)
                if res is not None:
                    best_c, best_r, best_s = res

    # --- Inflate-project-polish step ---
    if time.process_time() - t_start < budget_seconds - 0.5:
        try:
            c_inf, r_inf = _inflate_project(best_c, best_r, n, sweeps=200, factor=1e-6)
            # identify active set
            pairs, walls = _active_set(c_inf, r_inf, n, tol=1e-7)
            if pairs or walls:
                res = _kkt_polish(c_inf, r_inf, n, pairs, walls)
                if res is not None:
                    c_k, r_k = res
                    # validate strictly
                    if _is_valid(c_k, r_k, n, tol=0.0):
                        s_k = _score(c_k, r_k)
                        if s_k > best_s:
                            best_c = c_k.copy()
                            best_r = r_k.copy()
                            best_s = s_k
        except Exception:
            pass

    best_r = best_r - 1e-9
    best_r = np.maximum(best_r, 1e-9)
    best_c, best_r = _clean(best_c, best_r, n)
    best_r = np.maximum(best_r - 1e-12, 1e-9)

    out = np.column_stack([best_c, best_r])
    return out
